# Regular expression for extracting numeric values and currencies
NUM_RE = re.compile(r'^[\$\(\-]?\s*([0-9,]+(?:\.[0-9]+)?)\s*[\)\-$]*$')

def parse_number(cell: str) -> Optional[float]:
    """Return a numeric value from a cell, or None if it cannot be parsed."""
    cell = cell.strip()
    # remove commas and handle negative parentheses
    if not cell:
        return None
    if cell.startswith('(') and cell.endswith(')'):
        cell = '-' + cell[1:-1]
    m = NUM_RE.match(cell)
