                    eid = entity_id(key)
                    if eid not in ents:
                        ents[eid] = key
        elif node['kind'] == 'table':
            for row_index, row in table_rows(node):
                if not row:
                    continue
                # first column usually an entity descriptor
                first_col = next(iter(row.values()))
                if isinstance(first_col, str):
                    key = first_col.strip()
                    if key:
                        eid = entity_id(key)
                        if eid not in ents:
                            ents[eid] = key
    return [{"id": k, "description": v} for k, v in sorted(ents.items())]

def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the maximum year present in the scope."""
    years = set()
    for node in scope_nodes(doc, scope):
        if node['kind'] == 'table':
            for _, row in table_rows(node):
                for col_name in row:
                    y = extract_year(col_name)
                    if y:
                        years.add(y)
